  `inicia_tramite` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tipo_tramites_nombre_unique` (`nombre`),
  KEY `tipo_tramites_area_id_index` (`area_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tipo_tramite_doc_requerida`;
CREATE TABLE `tipo_tramite_doc_requerida` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tipo_tramite_id` int(10) unsigned NOT NULL,
  `doc_requerida_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `tipo_tramite_doc_requerida_tipo_tramite_id_index` (`tipo_tramite_id`),
  KEY `tipo_tramite_doc_requerida_doc_requerida_id_index` (`doc_requerida_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tramite_anses`;
CREATE TABLE `tramite_anses` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tramite_id` int(10) unsigned NOT NULL,
  `estado_anses_id` int(10) unsigned DEFAULT NULL,
  `fecha_remision` date DEFAULT NULL,
  `fecha_remision_vto` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `observations` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tramite_anses_tramite_id_index` (`tramite_id`),
  KEY `tramite_anses_estado_anses_id_index` (`estado_anses_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tramite_beneficios`;
CREATE TABLE `tramite_beneficios` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tramite_id` int(10) unsigned NOT NULL,
  `detalle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`detalle`)),
  `fecha_cobro` date NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tramite_beneficios_tramite_id_index` (`tramite_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tramite_clientes`;
CREATE TABLE `tramite_clientes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `area_id` int(10) unsigned NOT NULL,
  `cliente_id` int(10) unsigned NOT NULL,
  `requerimiento_id` int(10) unsigned NOT NULL,
  `expediente` varchar(50) DEFAULT NULL,
  `fecha_inicio` date DEFAULT NULL,
  `rep_origen_id` int(10) unsigned NOT NULL DEFAULT 0,
  `estado_tramite_id` int(10) unsigned NOT NULL,
  `secuencia` varchar(50) DEFAULT NULL,
  `oficina_ingreso_id` int(10) unsigned DEFAULT NULL,
  `oficina_egreso_id` int(10) unsigned DEFAULT NULL,
  `resolucion` tinyint(1) DEFAULT 0,
  `tipo_resolucion` int(11) DEFAULT 2,
  `nro_beneficio` varchar(50) DEFAULT NULL,
  `fecha_beneficio` date DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `archivar` tinyint(1) DEFAULT 0,
  `fecha_archivo` datetime DEFAULT NULL,
  `usuario_archivo_id` int(10) unsigned DEFAULT NULL,
  `fecha_ingreso` date DEFAULT NULL,
  `fecha_egreso` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `tramite_sig_id` int(10) unsigned DEFAULT NULL,
  `tramite_ant_id` int(10) unsigned DEFAULT NULL,
  `estado_anses_id` int(10) unsigned DEFAULT NULL,
  `fecha_remision` date DEFAULT NULL,
  `fecha_remision_vto` date DEFAULT NULL,
  `fecha_vto` date DEFAULT NULL,
  `deceased` tinyint(1) NOT NULL DEFAULT 0,
  `monto_beneficio` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tramite_clientes_area_id_index` (`area_id`),
  KEY `tramite_clientes_cliente_id_index` (`cliente_id`),
  KEY `tramite_clientes_requerimiento_id_index` (`requerimiento_id`),
  KEY `tramite_clientes_expediente_index` (`expediente`),
  KEY `tramite_clientes_rep_origen_id_index` (`rep_origen_id`),
  KEY `tramite_clientes_estado_tramite_id_index` (`estado_tramite_id`),
  KEY `tramite_clientes_oficina_ingreso_id_index` (`oficina_ingreso_id`),
  KEY `tramite_clientes_oficina_egreso_id_index` (`oficina_egreso_id`),
  KEY `tramite_clientes_usuario_archivo_id_index` (`usuario_archivo_id`),
  KEY `tramite_clientes_tramite_sig_id_index` (`tramite_sig_id`),
  KEY `tramite_clientes_tramite_ant_id_index` (`tramite_ant_id`),
  KEY `tramite_clientes_estado_anses_id_index` (`estado_anses_id`),
  KEY `tramite_clientes_fecha_vto_directorio_index` (`fecha_vto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tramite_conciliacion`;
CREATE TABLE `tramite_conciliacion` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tramite_id` int(10) unsigned NOT NULL,
  `detalle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`detalle`)),
  `fecha_cobro` date NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tramite_conciliacion_tramite_id_index` (`tramite_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `tramite_expedientes`;
CREATE TABLE `tramite_expedientes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tramite_id` int(10) unsigned NOT NULL,
  `area_id` int(10) unsigned NOT NULL,
  `nro_expediente` text NOT NULL,
  `juzgado_id` int(10) unsigned NOT NULL,
  `fecha` date NOT NULL,
  `estado_id` int(10) unsigned NOT NULL,
  `vuelta_anses` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `juicio_conciliado` tinyint(1) NOT NULL,
  `nro_conciliacion` varchar(50) DEFAULT NULL,
  `fecha_conciliacion` date DEFAULT NULL,
  `monto_conciliacion` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tramite_expedientes_tramite_id_index` (`tramite_id`),
  KEY `tramite_expedientes_area_id_index` (`area_id`),
  KEY `tramite_expedientes_juzgado_id_index` (`juzgado_id`),
  KEY `tramite_expedientes_estado_id_index` (`estado_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `username` varchar(50) NOT NULL,
  `responsable` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `visible` tinyint(1) DEFAULT 1,
  `time_level` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_username_unique` (`username`),
  KEY `users_responsable_index` (`responsable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_area`;
CREATE TABLE `user_area` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `area_id` int(10) unsigned NOT NULL,
  `responsable` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_area_user_id_index` (`user_id`),
  KEY `user_area_area_id_index` (`area_id`),
  KEY `user_area_responsable_index` (`responsable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `vencimientos`;
CREATE TABLE `vencimientos` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `fecha` datetime NOT NULL,
  `cliente_id` int(10) unsigned NOT NULL,
