  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vencimientos_vencible_id_vencible_type_index` (`vencible_id`,`vencible_type`),
  KEY `vencimientos_fecha_index` (`fecha`),
  KEY `vencimientos_cliente_id_index` (`cliente_id`),
  KEY `vencimientos_requerimiento_id_index` (`requerimiento_id`),
  KEY `vencimientos_tramite_id_index` (`tramite_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


